from pathlib import Path
import json, csv, hashlib
import numpy as np
import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt

ROOT=Path(__file__).resolve().parent; DATA=ROOT/'data'/'surrogate_2d'/'dataset'; OUT=ROOT/'results'/'surrogate_2d_pca_svd_20261012'
K_CAND=[0,1,2,5,10,15,20,30,40,50]
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def stats(y,p,mask):
 rows=[]
 for a,b,m in zip(y,p,mask):
  e=(a-b)[m]; rows.append((float(np.mean(abs(e))),float(np.sqrt(np.mean(e*e))),int(m.sum())))
 r=np.array(rows); return {'scene_mae_mean_db':float(r[:,0].mean()),'scene_rmse_mean_db':float(r[:,1].mean()),'scene_rmse_median_db':float(np.median(r[:,1])),'pooled_rmse_db':float(np.sqrt(np.sum((y-p)[mask]**2)/np.sum(mask))),'scene_count':len(rows),'valid_cell_count':int(r[:,2].sum())},rows
def main():
 OUT.mkdir(parents=True,exist_ok=False); man=json.loads((DATA/'splits/split_manifest.json').read_text(encoding='utf-8')); ids=man['splits']; assert [len(ids[x]) for x in ('train','validation','test')]==[70,15,15]
 allids=ids['train']+ids['validation']; arr={s:np.load(DATA/'npy'/f'{s}.npy',allow_pickle=False).astype(float) for s in allids}; y=np.stack([arr[s].reshape(-1) for s in allids]); masks=np.stack([np.isfinite(arr[s]).reshape(-1) for s in allids]); tr=np.arange(70); va=np.arange(70,85)
 train_valid=masks[tr]; learnable=train_valid.any(axis=0); excluded_cells=int((~learnable).sum()); mean=np.divide(np.where(train_valid,y[:70],0).sum(0),train_valid.sum(0),out=np.zeros(400),where=train_valid.sum(0)>0); filled=np.where(np.isfinite(y),y,mean); X=filled[:70,learnable]; Xc=X-X.mean(0); U,S,Vt=np.linalg.svd(Xc,full_matrices=False); rank=int(np.linalg.matrix_rank(Xc)); var=S*S; cum=np.cumsum(var)/var.sum() if var.sum() else np.zeros_like(var); ks=[k for k in K_CAND if k<=rank]
 np.savez_compressed(OUT/'pca_model.npz',mean_map=mean.reshape(20,20),components=Vt[:rank],singular_values=S,learnable_mask=learnable.reshape(20,20),train_valid_mask=train_valid,rank=rank)
 results=[]; predictions={}
 for k in ks:
  basis=Vt[:k]; defrec=lambda Z: mean[learnable]+(Z-mean[learnable])@basis.T@basis if k else np.tile(mean[learnable],(len(Z),1))
  pred_tr=np.tile(mean,(70,1)); pred_va=np.tile(mean,(15,1)); pred_tr[:,learnable]=defrec(filled[:70,learnable]); pred_va[:,learnable]=defrec(filled[70:,learnable]); evtr=masks[:70]&learnable; evva=masks[70:]&learnable
  ts,_=stats(y[:70],pred_tr,evtr); vs,detail=stats(y[70:],pred_va,evva); results.append({'k':k,'train':ts,'validation':vs,'cumulative_explained_variance':float(cum[k-1]) if k else 0.0,'coefficient_count':k,'original_output_count':400,'validation_scene_details':[{ 'sample_id':ids['validation'][i], 'mae_db':d[0], 'rmse_db':d[1], 'valid_cells':d[2]} for i,d in enumerate(detail)]}); predictions[k]=pred_va
 with (OUT/'metrics.json').open('w',encoding='utf-8') as f: json.dump({'dataset':{'npy_count':len(list((DATA/'npy').glob('*.npy'))),'shape':[20,20],'array_order':man['grid']['array_order'],'offset_m':man['grid']['offset_m'],'metadata_sha256':sha(DATA/'metadata.csv'),'split_manifest_sha256':sha(DATA/'splits/split_manifest.json'),'split_sizes':{x:len(ids[x]) for x in ids}},'preprocessing':{'train_cell_mean_imputation':True,'standardization':False,'preserve_original_nan_masks':True,'learnable_cells':int(learnable.sum()),'excluded_unseen_cells':excluded_cells,'evaluation_excludes_original_nan_and_unlearnable':True,'bias_note':'train-mean imputation is a biased baseline; NaN obstacle cells are not treated as 0 dB'},'svd':{'rank':rank,'singular_values_count':len(S),'explained_variance_basis':'filled, centered train matrix'},'results':results,'test_evaluated':False,'thresholds':{'mean_scene_rmse_le_0.5_db':next((r['k'] for r in results if r['validation']['scene_rmse_mean_db']<=.5),None),'mean_scene_rmse_le_1.0_db':next((r['k'] for r in results if r['validation']['scene_rmse_mean_db']<=1.0),None)},'limitations':['Explained variance is for the imputed train matrix, not field or AI accuracy.','No test evaluation or component selection used test data.']},f,ensure_ascii=False,indent=2)
 with (OUT/'k_results.csv').open('w',newline='',encoding='utf-8-sig') as f:
  w=csv.writer(f); w.writerow(['k','split','mae_db','scene_rmse_mean_db','scene_rmse_median_db','pooled_rmse_db','cumulative_explained_variance']); [w.writerow([r['k'],sp,r[sp]['scene_mae_mean_db'],r[sp]['scene_rmse_mean_db'],r[sp]['scene_rmse_median_db'],r[sp]['pooled_rmse_db'],r['cumulative_explained_variance']]) for r in results for sp in ('train','validation')]
 x=[r['k'] for r in results]; fig,ax=plt.subplots(); ax.plot(x,[r['train']['scene_rmse_mean_db'] for r in results],'o-',label='train'); ax.plot(x,[r['validation']['scene_rmse_mean_db'] for r in results],'o-',label='validation'); ax.axhline(.5,color='k',ls='--'); ax.set(xlabel='k',ylabel='mean scene RMSE (dB)'); ax.grid(alpha=.25); ax.legend(); fig.tight_layout(); fig.savefig(OUT/'reconstruction_error_by_k.png',dpi=180); plt.close(fig)
 fig,ax=plt.subplots(); ax.plot(range(1,rank+1),cum[:rank],'o-'); ax.set(xlabel='k',ylabel='cumulative explained variance'); ax.grid(alpha=.25); fig.tight_layout(); fig.savefig(OUT/'cumulative_explained_variance.png',dpi=180); plt.close(fig)
 chosen=next((r['k'] for r in results if r['validation']['scene_rmse_mean_db']<=.5),max(x)); v=predictions[chosen]; lo=min(np.nanmin(y[70:][masks[70:]]),np.nanmin(v[masks[70:] ])); hi=max(np.nanmax(y[70:][masks[70:]]),np.nanmax(v[masks[70:]])); cmap=plt.get_cmap('viridis').copy(); cmap.set_bad('white'); ec=plt.get_cmap('coolwarm').copy(); ec.set_bad('white')
 for j in range(3):
  sid=ids['validation'][j]; m=masks[70+j]&learnable; orig=np.where(m,y[70+j],np.nan).reshape(20,20); rec=np.where(m,v[j],np.nan).reshape(20,20); err=np.where(m,v[j]-y[70+j],np.nan).reshape(20,20); fig,ax=plt.subplots(1,3,figsize=(12,4));
  for a,z,t,c,vr in zip(ax,(orig,rec,err),('original','reconstruction','error'),(cmap,cmap,ec),((lo,hi),(lo,hi),(-max(abs(np.nanmin(err)),abs(np.nanmax(err))),max(abs(np.nanmin(err)),abs(np.nanmax(err)))))): a.imshow(z,origin='lower',cmap=c,vmin=vr[0],vmax=vr[1]); a.set_title(t); a.set_xticks([]); a.set_yticks([]); fig.colorbar(a.images[0],ax=a,shrink=.75)
  fig.suptitle(f'{sid} validation | k={chosen} | shared original/reconstruction scale'); fig.tight_layout(); fig.savefig(OUT/f'{sid}_maps.png',dpi=160); plt.close(fig)
 (OUT/'README.md').write_text(f'''# 2D acoustic-map PCA/SVD reconstruction\n\n실행: `.venv\\Scripts\\python.exe pca_svd_reconstruction_2d.py`\n\n기존 `split_manifest.json`의 train 70 / validation 15 / test 15를 그대로 사용했습니다. NPY는 100개이며 20×20, y,x 순서, 0.5 m offset입니다. 기존 생성 코드는 유효 영역 최대값을 0 dB로 정규화하고 장애물 내부를 NaN으로 저장합니다.\n\nTrain에서 칸별 평균으로 NaN을 채운 뒤 중심화 SVD를 수행했습니다. train에서 한 번도 유효하지 않은 칸은 PCA에서 제외했고, 평가에서는 원래 NaN과 제외 칸을 모두 제외했습니다. 장애물 내부를 0 dB로 취급하지 않았습니다. 표준화, 복원 후 재정규화·클리핑은 없습니다. 이 결측 대체는 편향 가능한 기준 실험입니다.\n\n선택된 그림 k: {chosen}. val 평균 장면 RMSE 0.5 dB 이하 후보를 우선 사용하고, 없으면 최대 유효 k를 사용했습니다. 설명분산은 결측을 채운 train 행렬 기준이며 실측 또는 AI 정확도가 아닙니다. test는 평가·성분 선택에 사용하지 않았습니다.\n''',encoding='utf-8')
 print(json.dumps({'output':str(OUT),'rank':rank,'chosen_k':chosen,'thresholds':{'0.5':next((r['k'] for r in results if r['validation']['scene_rmse_mean_db']<=.5),None),'1.0':next((r['k'] for r in results if r['validation']['scene_rmse_mean_db']<=1.0),None)}},ensure_ascii=False))
if __name__=='__main__': main()
